(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const setV = (el, v) => { const d = Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el), 'value').set; d.call(el, v); el.dispatchEvent(new Event('input', { bubbles: true })); };
  const out = {};
  // 建一个卍解作品并贴代码
  const nameInput = document.querySelector('.tb-card .tb-input');
  if (!nameInput) return JSON.stringify({ error: '新建面板没打开' });
  setV(nameInput, '卍解外观检查');
  [...document.querySelectorAll('.tb-diff-opt')].find((b) => b.textContent.includes('卍解'))?.click();
  await sleep(300);
  [...document.querySelectorAll('.tb-btn-primary')].find((b) => b.textContent.includes('创建'))?.click();
  for (let i = 0; i < 20; i++) { await sleep(500); if (document.querySelector('.pc-wrap')) break; }

  // 面板应该在卡片里
  out.panelInCard = !!document.querySelector('.pc-wrap')?.closest('.pj-card');
  out.cardTitle = document.querySelector('.pc-wrap')?.closest('.pj-card')?.querySelector('.pj-card-title')?.textContent?.trim() || null;
  out.leadText = [...document.querySelectorAll('.pc-wrap')?.length ? document.querySelectorAll('.pj-card .pj-text') : []].map((p) => p.textContent.trim().slice(0, 26)).slice(-1)[0] || null;

  [...document.querySelectorAll('.pc-btn')].find((b) => b.textContent.includes('直接贴代码'))?.click();
  await sleep(700);
  const inputs = [...document.querySelectorAll('.pc-input')];
  setV(inputs[0], 'main.c');
  setV(inputs[1], '主程序');
  setV(document.querySelector('.pc-textarea'), '#include <stm32f10x.h>\n// 中文注释\nint main(void) { return 0; }\n');
  [...document.querySelectorAll('.pc-btn-primary')].find((b) => b.textContent.includes('放进作品'))?.click();
  await sleep(2200);
  out.codeFile = document.querySelector('.pc-item-name')?.textContent || null;
  document.querySelector('.pc-wrap')?.scrollIntoView({ block: 'start' });
  await sleep(800);
  return JSON.stringify(out);
})()
